# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">SİNÜS VE KOSİNÜS DENKLEMLERİNİN GENEL ÇÖZÜM KÜMELERİ (12.3.2.1)</text>\n  <rect x="20" y="45" width="320" height="198" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="180" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">1. sin f(x) = sin α Denklemi (-1 ≤ a ≤ 1)</text>\n  <text x="35" y="92" font-size="10.5" fill="#1e3a8a">• Birim çemberde I. ve II. bölgede sinüs aynı işaretlidir:</text>\n  <rect x="35" y="104" width="290" height="58" rx="6" fill="#ffffff" stroke="#60a5fa"/>\n  <text x="180" y="125" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1d4ed8">f(x) = α + 2kπ   (veya α + 360°·k)</text>\n  <text x="180" y="148" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1d4ed8">f(x) = (π - α) + 2kπ   (veya 180° - α + 360°·k)</text>\n  <text x="35" y="182" font-size="10.5" fill="#1e3a8a">• <tspan font-weight="bold">Özel Durumlar (k ∈ Z):</tspan></text>\n  <text x="43" y="200" font-size="10" fill="#1e3a8a">• sin x = 0 ⇒ x = kπ   |   sin x = 1 ⇒ x = π/2 + 2kπ</text>\n  <text x="43" y="218" font-size="10" fill="#1e3a8a">• sin x = -1 ⇒ x = 3π/2 + 2kπ (veya -π/2 + 2kπ)</text>\n  <rect x="360" y="45" width="320" height="198" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="520" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#166534">2. cos f(x) = cos α Denklemi (-1 ≤ a ≤ 1)</text>\n  <text x="375" y="92" font-size="10.5" fill="#14532d">• Birim çemberde I. ve IV. bölgede kosinüs aynı işaretlidir:</text>\n  <rect x="375" y="104" width="290" height="58" rx="6" fill="#ffffff" stroke="#22c55e"/>\n  <text x="520" y="125" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#15803d">f(x) = α + 2kπ   (veya α + 360°·k)</text>\n  <text x="520" y="148" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#15803d">f(x) = -α + 2kπ   (veya -α + 360°·k)</text>\n  <text x="375" y="182" font-size="10.5" fill="#14532d">• <tspan font-weight="bold">Özel Durumlar ve Dönüşüm (k ∈ Z):</tspan></text>\n  <text x="383" y="200" font-size="10" fill="#14532d">• cos x = 0 ⇒ x = π/2 + kπ   |   cos x = 1 ⇒ x = 2kπ</text>\n  <text x="383" y="218" font-size="10" font-weight="bold" fill="#166534">• sin A = cos B ise cos B = sin(π/2 - B) yazılır!</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">TANJANT, KOTANJANT VE HOMOJEN DENKLEMLERİN ÇÖZÜMÜ</text>\n  <rect x="20" y="45" width="320" height="198" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="180" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#92400e">tan f(x) = tan α ve cot f(x) = cot α</text>\n  <text x="35" y="92" font-size="10.5" fill="#78350f">• Tanjant ve kotanjantın esas periyodu <tspan font-weight="bold">π (180°)</tspan> olduğu</text>\n  <text x="43" y="108" font-size="10.5" fill="#78350f">için tek bir çözüm dalı yeterlidir (a ∈ R):</text>\n  <rect x="35" y="120" width="290" height="44" rx="6" fill="#ffffff" stroke="#f59e0b"/>\n  <text x="180" y="147" text-anchor="middle" font-size="12" font-weight="bold" fill="#b45309">f(x) = α + kπ   (veya α + 180°·k, k ∈ Z)</text>\n  <text x="35" y="184" font-size="10.5" fill="#78350f">• <tspan font-weight="bold">Önemli Uyarı (Tanımsızlık Kontrolü):</tspan></text>\n  <text x="43" y="202" font-size="10" fill="#78350f">Paydayı sıfır yapan (tan için π/2 + kπ, cot için kπ)</text>\n  <text x="43" y="218" font-size="10" font-weight="bold" fill="#92400e">değerler çözüm kümesinden mutlaka çıkarılır!</text>\n  <rect x="360" y="45" width="320" height="198" rx="10" fill="#fae8ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="520" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#6b21a8">Homojen ve Çarpanlara Ayrılan Denklemler</text>\n  <text x="375" y="92" font-size="10.5" fill="#581c87">• <tspan font-weight="bold">1. Dereceden Homojen (a·sin x + b·cos x = 0):</tspan></text>\n  <text x="383" y="108" font-size="10.5" fill="#581c87">Her iki taraf cos x\'e bölünür: <tspan font-weight="bold">tan x = -b / a</tspan></text>\n  <text x="375" y="132" font-size="10.5" fill="#581c87">• <tspan font-weight="bold">2. Dereceden Homojen:</tspan></text>\n  <text x="383" y="148" font-size="10" fill="#581c87">a·sin²x + b·sin x·cos x + c·cos²x = 0 denkleminde</text>\n  <text x="383" y="164" font-size="10" fill="#581c87">cos²x\'e bölünerek <tspan font-weight="bold">a·tan²x + b·tan x + c = 0</tspan> çözülür.</text>\n  <text x="375" y="188" font-size="10.5" fill="#581c87">• <tspan font-weight="bold">El-Battânî (858–929):</tspan></text>\n  <text x="383" y="204" font-size="10" fill="#581c87">Sinüs, kosinüs, tanjant ve kotanjant özdeşliklerini</text>\n  <text x="383" y="220" font-size="10" fill="#581c87">astronomik denklemlerde ilk kullanan İslam âlimidir.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">LİNEER TRİGONOMETRİK DENKLEM: a·sin x + b·cos x = c</text>\n  <rect x="25" y="45" width="310" height="198" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="180" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">Çözüm (Gerçek Kök) Varlık Şartı</text>\n  <text x="40" y="92" font-size="10.5" fill="#1e3a8a">• A(x) = a·sin x + b·cos x ifadesinin alabileceği</text>\n  <text x="48" y="108" font-size="10.5" fill="#1e3a8a">en büyük değer <tspan font-weight="bold">+kök(a² + b²)</tspan>, en küçük değer</text>\n  <text x="48" y="124" font-size="10.5" fill="#1e3a8a">ise <tspan font-weight="bold">-kök(a² + b²)</tspan> değeridir.</text>\n  <rect x="40" y="138" width="280" height="44" rx="6" fill="#ffffff" stroke="#60a5fa"/>\n  <text x="180" y="164" text-anchor="middle" font-size="12" font-weight="bold" fill="#1d4ed8">c² ≤ a² + b²   ⇒   Çözüm Kümesi Boş Değil!</text>\n  <text x="40" y="202" font-size="10.5" font-weight="bold" fill="#b91c1c">• Eğer c² &gt; a² + b² ise denklemin gerçek</text>\n  <text x="48" y="218" font-size="10.5" font-weight="bold" fill="#b91c1c">sayılarda çözümü yoktur: ÇK = ∅</text>\n  <rect x="365" y="45" width="310" height="198" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="520" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">Yardımcı Açı (tan φ = b / a) Yöntemi</text>\n  <text x="380" y="92" font-size="10.5" fill="#14532d">1. Denklemde her iki taraf <tspan font-weight="bold">a</tspan> sayısına bölünür ve</text>\n  <text x="388" y="108" font-size="10.5" font-weight="bold" fill="#15803d">b / a = tan φ = sin φ / cos φ</text>\n  <text x="388" y="124" font-size="10.5" fill="#14532d">yardımcı açısı tanımlanır.</text>\n  <text x="380" y="148" font-size="10.5" fill="#14532d">2. Toplam formülü uygulanır:</text>\n  <text x="388" y="166" font-size="11" font-weight="bold" fill="#15803d">sin x · cos φ + cos x · sin φ = sin(x + φ)</text>\n  <text x="380" y="190" font-size="10.5" fill="#14532d">3. Veya doğrudan <tspan font-weight="bold">R = kök(a² + b²)</tspan> ile bölünerek</text>\n  <text x="388" y="208" font-size="11" font-weight="bold" fill="#166534">sin(x + φ) = c / kök(a² + b²)</text>\n  <text x="388" y="224" font-size="10" fill="#14532d">temel sinüs denklemine dönüştürülüp çözülür.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
